/* User column presentation; table controls are included during the build. */
(function () {
    'use strict';
    var VERIFICATION_STATES = {
        idle: 'Подтвердить верификацию', pending: 'Подтверждение выполняется',
        denied: 'Нет права подтверждать верификацию', failed: 'Подтверждение не выполнено',
        unknown: 'Результат неизвестен; сначала обновите данные'
    };
    var verification = new WeakMap();
    function restoreVerificationFocus(cell, ownedFocus) {
        if (!ownedFocus || !cell.isConnected) return;
        var button = cell.querySelector('.js-user-verify');
        if (button && !button.disabled) button.focus();
        else {
            // Keep keyboard position when a pending/result snapshot removes its trigger.
            if (!cell.hasAttribute('tabindex')) cell.setAttribute('tabindex', '-1');
            cell.focus();
        }
    }
    function renderVerification(cell, snapshot) {
        var ownedFocus = !!cell && cell.contains(document.activeElement);
        var row = cell && cell.closest('tr[data-key]');
        if (!row || !snapshot || snapshot.user_id !== row.getAttribute('data-key') ||
            !Object.prototype.hasOwnProperty.call(VERIFICATION_STATES, snapshot.state) ||
            ![true, false, null].includes(snapshot.verified) || ![true, false, null].includes(snapshot.can_set_verified)) {
            var oldButton = cell && cell.querySelector('.js-user-verify');
            if (oldButton) { oldButton.disabled = true; oldButton.title = VERIFICATION_STATES.unknown; }
            if (cell) verification.delete(cell);
            if (cell) restoreVerificationFocus(cell, ownedFocus);
            return false;
        }
        snapshot = { user_id: snapshot.user_id, verified: snapshot.verified, state: snapshot.state, can_set_verified: snapshot.can_set_verified };
        verification.set(cell, snapshot);
        cell.setAttribute('data-user-verified', snapshot.verified === null ? 'unknown' : String(snapshot.verified));
        cell.setAttribute('data-verification-state', snapshot.state);
        cell.replaceChildren();
        if (snapshot.verified === true) {
            var badge = document.createElement('span');
            badge.className = 'label label-success';
            badge.textContent = 'Да';
            badge.title = 'Верифицирован';
            badge.setAttribute('aria-label', 'Верифицирован');
            cell.appendChild(badge);
            restoreVerificationFocus(cell, ownedFocus);
            return true;
        }
        if (snapshot.verified === null) {
            var missing = document.createElement('span');
            missing.textContent = '—';
            missing.title = VERIFICATION_STATES.unknown;
            cell.appendChild(missing);
            restoreVerificationFocus(cell, ownedFocus);
            return true;
        }
        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'btn btn-xs btn-success btn-block js-user-verify';
        button.setAttribute('data-user-id', snapshot.user_id);
        button.textContent = 'Подтвердить';
        button.title = VERIFICATION_STATES[snapshot.state];
        button.disabled = snapshot.can_set_verified !== true || !['idle', 'failed'].includes(snapshot.state);
        button.setAttribute('aria-busy', String(snapshot.state === 'pending'));
        button.addEventListener('click', function (event) {
            event.preventDefault();
            if (button.disabled || !button.isConnected || verification.get(cell) !== snapshot) return;
            renderVerification(cell, { user_id: snapshot.user_id, verified: false, state: 'pending', can_set_verified: false });
            cell.dispatchEvent(new CustomEvent('admin:userverificationrequest', {
                bubbles: true, detail: { user_id: snapshot.user_id, action: 'set_verified', verified: true }
            }));
        });
        cell.appendChild(button);
        restoreVerificationFocus(cell, ownedFocus);
        return true;
    }
    function initVerification() {
        document.querySelectorAll('[name="UserSearch[last_login_at]"]').forEach(function (filter) {
            if (filter.getAttribute('data-filter-ready') !== 'true') {
                filter.disabled = true;
                filter.title = 'Фильтр последнего входа требует серверной доработки';
            }
        });
        document.querySelectorAll('.content table.table td[data-user-verified]').forEach(function (cell) {
            if (verification.has(cell)) return;
            var row = cell.closest('tr[data-key]');
            if (!row) return;
            var raw = cell.getAttribute('data-user-verified');
            renderVerification(cell, { user_id: row.getAttribute('data-key'), verified: raw === 'true' ? true : raw === 'false' ? false : null,
                state: 'idle', can_set_verified: null });
        });
    }
    function updateUserColumns() {
        document.querySelectorAll('.content table.table').forEach(function (table) {
            if (!table.tHead || !table.tHead.rows.length) return;
            var header = table.tHead.rows[0];
            var registration = header.querySelector('[data-sort="created_at"], [data-sort="-created_at"]');
            var login = header.querySelector('[data-sort="last_login_at"], [data-sort="-last_login_at"]');
            if (registration) registration.textContent = 'Регистрация';
            if (login) login.textContent = 'Вход';
            // Resolve columns by their headers so the selection column cannot shift alignment.
            Array.from(header.cells).forEach(function (cell) {
                var label = cell.textContent.trim();
                if (!['Регистрация', 'Вход', 'Верификация', 'Вериф.', 'Премиум', 'Блокировка', 'Статус блокировки'].includes(label)) return;
                if (label === 'Вериф.') (cell.querySelector('a') || cell).textContent = 'Верификация';
                Array.from(table.rows).forEach(function (row) {
                    if (row.cells.length === header.cells.length) row.cells[cell.cellIndex].classList.add('user-status-cell');
                });
            });
        });
    }
    function init() { updateUserColumns(); initVerification(); }
    window.AdminUserVerification = { render: renderVerification, init: initVerification };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
    if (window.jQuery) window.jQuery(document).on('pjax:end.userColumns', init);
}());

