/* Compact date presentation only. Preserve server values, timezone and sorting URLs. */
(function () {
    'use strict';
    if (window.AdminTableDates) return;
    var TABLE_SELECTOR = '.content table.table'; // Record grids, excluding key-value detail tables.
    var DATE_SORT_KEYS = ['created_at', 'updated_at', 'last_login_at']; // Existing Yii date attributes.
    var DATE_LABELS = ['дата', 'создано', 'обновлено', 'время регистрации', 'последний вход', 'вход', 'last pay', 'last payout', 'requested', 'запрошен']; // Date columns without native sort links.
    var MONTHS = { jan: 1, янв: 1, feb: 2, фев: 2, мар: 3, mar: 3, апр: 4, apr: 4,
        мая: 5, май: 5, may: 5, июн: 6, jun: 6, июл: 7, jul: 7, авг: 8, aug: 8,
        сен: 9, sep: 9, окт: 10, oct: 10, ноя: 11, nov: 11, дек: 12, dec: 12 }; // Explicit snapshot month names; no browser-dependent date parsing.

    function compactDate(original) {
        var text = original.replace(/\s+/g, ' ').trim();
        var numeric = text.match(/^(\d{1,2})\.(\d{1,2})\.(\d{2}|\d{4})(?: (\d{1,2}):(\d{2})(?::\d{2})?)?$/);
        var named = text.match(/^(?:(\d{1,2}) ([a-zа-яё]+)\.? (\d{4})|([a-zа-яё]+)\.? (\d{1,2}), (\d{4}))(?:\s*г\.?)?,?(?: (\d{1,2}):(\d{2})(?::\d{2})?(?: (AM|PM))?)?$/i);
        var day, month, year, hour, minute;
        if (numeric) {
            day = numeric[1]; month = numeric[2]; year = numeric[3]; hour = numeric[4]; minute = numeric[5];
        } else if (named) {
            day = named[1] || named[5];
            month = MONTHS[(named[2] || named[4]).toLowerCase().slice(0, 3)];
            year = named[3] || named[6]; hour = named[7]; minute = named[8];
            if (!month) return original;
            if (named[9]) hour = String(Number(hour) % 12 + (named[9].toUpperCase() === 'PM' ? 12 : 0));
        } else return original;
        var result = String(day).padStart(2, '0') + '.' + String(month).padStart(2, '0') + '.' + year.slice(-2);
        return result + (hour === undefined ? '' : ' ' + String(hour).padStart(2, '0') + ':' + minute);
    }

    function init() {
        document.querySelectorAll(TABLE_SELECTOR).forEach(function (table) {
            if (!table.tHead || !table.tHead.rows.length) return;
            Array.from(table.tHead.rows[0].cells).forEach(function (header) {
                var link = header.querySelector('[data-sort]');
                var key = link ? link.getAttribute('data-sort').replace(/^-/, '') : '';
                if (!DATE_SORT_KEYS.includes(key) && !DATE_LABELS.includes(header.textContent.trim().toLowerCase())) return;
                var index = header.cellIndex;
                Array.from(table.rows).forEach(function (row) {
                    if (row.cells.length !== header.parentElement.cells.length) return;
                    var cell = row.cells[index];
                    cell.classList.add('grid-date-cell');
                    if (row.parentElement.tagName !== 'TBODY' || cell.children.length || cell.dataset.dateOriginal !== undefined) return;
                    var original = cell.textContent.trim();
                    var formatted = compactDate(original);
                    cell.dataset.dateOriginal = original;
                    if (formatted !== original) {
                        if (!cell.hasAttribute('title')) cell.title = original;
                        cell.textContent = formatted;
                    }
                });
            });
        });
    }
    window.AdminTableDates = { init: init, compactDate: compactDate };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
    if (window.jQuery) window.jQuery(document).on('pjax:end.tableDates', init);
}());

