/* Synchronized native scrollbars. Does not change table data or server requests. */
(function () {
    'use strict';
    if (window.AdminTableScroll) return;
    var TABLE_SELECTOR = '.content table.table'; // Grids inside their existing horizontal scroll containers.
    var OVERFLOW_TOLERANCE = 1; // Ignore subpixel rounding when deciding whether scrolling is needed.
    var scrollbars = new Map();

    function init() {
        scrollbars.forEach(function (state, table) {
            if (table.isConnected && state.bar.isConnected && table.parentElement === state.parent) return;
            state.observer.disconnect();
            state.parent.removeEventListener('scroll', state.syncFromTable);
            state.bar.remove();
            scrollbars.delete(table);
        });
        document.querySelectorAll(TABLE_SELECTOR).forEach(function (table) {
            if (scrollbars.has(table)) {
                scrollbars.get(table).update();
                return;
            }
            var parent = table.parentElement;
            if (!/auto|scroll/.test(getComputedStyle(parent).overflowX)) return;
            var bar = document.createElement('div');
            bar.className = 'table-top-scrollbar';
            bar.tabIndex = 0;
            bar.setAttribute('role', 'region');
            bar.setAttribute('aria-label', '\u0413\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u0440\u043e\u043a\u0440\u0443\u0442\u043a\u0430 \u0442\u0430\u0431\u043b\u0438\u0446\u044b');
            var spacer = document.createElement('div');
            spacer.className = 'table-top-scrollbar-spacer';
            spacer.setAttribute('aria-hidden', 'true');
            bar.appendChild(spacer);
            table.before(bar);
            function syncFromTable() {
                if (bar.scrollLeft !== parent.scrollLeft) bar.scrollLeft = parent.scrollLeft;
            }
            function update() {
                var width = parent.clientWidth;
                var contentWidth = Math.max(table.offsetWidth, table.scrollWidth);
                bar.hidden = contentWidth - width <= OVERFLOW_TOLERANCE;
                bar.style.width = width + 'px';
                spacer.style.width = contentWidth + 'px';
                syncFromTable();
            }
            bar.addEventListener('scroll', function () {
                if (!bar.hidden && parent.scrollLeft !== bar.scrollLeft) parent.scrollLeft = bar.scrollLeft;
            }, { passive: true });
            parent.addEventListener('scroll', syncFromTable, { passive: true });
            var observer = new ResizeObserver(update);
            observer.observe(parent);
            observer.observe(table);
            scrollbars.set(table, { bar: bar, parent: parent, observer: observer, update: update, syncFromTable: syncFromTable });
            update();
        });
    }
    window.AdminTableScroll = { init: init };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
    if (window.jQuery) window.jQuery(document).on('pjax:end.tableScroll', init);
}());

