/* Shared server-pagination presentation. Never slices local rows or invents a pager. */
(function () {
    'use strict';
    if (window.AdminTablePagination) return;
    var TABLE_SELECTOR = '.content .grid-view > table.table,.content table.balance-grid-view,.content table.transactions-grid-view';
    var PAGE_SIZE_PARAM = 'per-page'; // Yii Pagination pageSizeParam.
    var PAGE_PARAM = 'page'; // Yii Pagination pageParam; reset when changing size.
    var IS_STATIC_PREVIEW = !!document.querySelector('script[src="assets/preview-only.js"]'); // No live navigation from snapshots.
    var controlTables = new WeakMap();

    function configuration(table) {
        var options;
        try { options = JSON.parse(table.getAttribute('data-page-sizes')); }
        catch (error) { return null; }
        var size = Number(table.getAttribute('data-page-size'));
        var sizeParam = table.getAttribute('data-page-size-param') || PAGE_SIZE_PARAM;
        var pageParam = table.getAttribute('data-page-param') || PAGE_PARAM;
        if (!Array.isArray(options) || !options.length || options.some(function (value) {
            return !Number.isSafeInteger(value) || value < 1 || value > 10000;
        }) || new Set(options).size !== options.length || !options.includes(size) ||
            !/^[A-Za-z][A-Za-z0-9_-]*$/.test(sizeParam) || !/^[A-Za-z][A-Za-z0-9_-]*$/.test(pageParam) || sizeParam === pageParam) return null;
        return { sizes: options, size: size, sizeParam: sizeParam, pageParam: pageParam };
    }

    function renderSettings(table, select) {
        var config = configuration(table);
        select.replaceChildren();
        if (!config) {
            var unknown = document.createElement('option');
            unknown.value = '';
            unknown.textContent = '—';
            unknown.selected = true;
            select.appendChild(unknown);
        }
        (config ? config.sizes : []).forEach(function (value) {
            var option = document.createElement('option');
            option.value = String(value);
            option.textContent = String(value);
            option.selected = value === config.size;
            select.appendChild(option);
        });
        select.disabled = IS_STATIC_PREVIEW || !config;
        select.title = IS_STATIC_PREVIEW ? 'Статический снимок, серверная пагинация недоступна' : !config ? 'Настройки пагинации не подтверждены сервером' : '';
    }

    function init() {
        document.querySelectorAll(TABLE_SELECTOR).forEach(function (table) {
            var parent = table.parentElement;
            var existing = parent.querySelector('.admin-pagination-bar .admin-page-size');
            if (existing) {
                controlTables.set(existing, table);
                renderSettings(table, existing);
                return;
            }
            var pager = parent.querySelector('.pagination');
            if (pager) {
                pager.setAttribute('aria-label', 'Страницы таблицы');
                var current = pager.querySelector('.active > a,.active > span');
                if (current) current.setAttribute('aria-current', 'page');
            }
            var bar = document.createElement('div');
            bar.className = 'admin-pagination-bar';
            var label = document.createElement('label');
            label.className = 'admin-page-size-label';
            label.appendChild(document.createTextNode('На странице'));
            var select = document.createElement('select');
            select.className = 'form-control input-sm admin-page-size';
            select.setAttribute('aria-label', 'Количество записей на странице');
            // Retain the page's existing CSS without duplicating pagination behavior.
            var prefix = table.matches('.balance-grid-view') ? 'balance' : table.matches('.transactions-grid-view') ? 'tx'
                : table.querySelector('.order-col-guid') ? 'order' : '';
            if (prefix) {
                bar.classList.add(prefix + '-pagination-bar');
                label.classList.add(prefix + '-page-size-label');
                select.classList.add(prefix + '-page-size');
            }
            renderSettings(table, select);
            controlTables.set(select, table);
            label.appendChild(select);
            table.after(bar);
            bar.appendChild(label);
            if (pager) bar.appendChild(pager);
            select.addEventListener('change', function () {
                var currentTable = controlTables.get(select);
                if (!currentTable || !document.contains(currentTable) || !document.contains(select) || select.disabled) return;
                var pageSize = Number(select.value);
                var config = configuration(currentTable);
                // A selection is intent, not proof that the server applied the new size.
                renderSettings(currentTable, select);
                if (IS_STATIC_PREVIEW || !config || !config.sizes.includes(pageSize)) return;
                // A backend PJAX adapter may cancel the default full-page navigation.
                var event = new CustomEvent('admin:pagesizechange', {
                    bubbles: true, cancelable: true, detail: { pageSize: pageSize, page: 1 }
                });
                if (!currentTable.dispatchEvent(event)) return;
                var url = new URL(window.location.href);
                url.searchParams.set(config.sizeParam, String(pageSize));
                url.searchParams.set(config.pageParam, '1');
                window.location.assign(url.href);
            });
        });
    }
    window.AdminTablePagination = { init: init };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
    if (window.jQuery) window.jQuery(document).on('pjax:end.tablePagination', init);
}());
